  SETS.forEach(function(S) {
    var sh = SpreadsheetApp.openById(S.id).getSheetByName('Cards');
    var last = sh.getLastRow();
    var col = sh.getRange(1, 1, last, 1).getValues().map(function(r){return r[0];});
    var add = [], upd = 0;
    S.data.forEach(function(d) {
      var i = col.indexOf(d[0]);
      if (i >= 0) { sh.getRange(i + 1, 2, 1, 4).setValues([[d[1], d[2], d[3], d[4]]]); upd++; }
      else add.push(d);
    });
    if (add.length) {
      var start = last + 1;
      sh.insertRowsAfter(last, add.length);
      sh.getRange(last, 1, 1, 5).copyTo(sh.getRange(start, 1, add.length, 5), SpreadsheetApp.CopyPasteType.PASTE_FORMAT, false);
      sh.getRange(last, 6, 1, 4).copyTo(sh.getRange(start, 6, add.length, 4));
      sh.getRange(start, 1, add.length, 5).setValues(add);
      var k = []; for (var j = 0; j < add.length; j++) k.push(["English Language"]);
      sh.getRange(start, 11, add.length, 1).setValues(k);
    }
    out.push(S.n + ' updated ' + upd + ' added ' + add.length);
  });
  Logger.log(out.join(', '));
